const fs = require('node:fs');
const path = require('node:path');

const ENDPOINT = 'http://127.0.0.1:56148/status';
const OUT_DIR = path.join(__dirname, 'results');
const OUT_FILE = path.join(OUT_DIR, 'status.json');

async function main() {
  const res = await fetch(ENDPOINT);
  if (!res.ok) {
    throw new Error(`Unexpected HTTP status: ${res.status}`);
  }
  const data = await res.json();
  const status = data.status;
  if (status !== 200) {
    throw new Error(`Expected status=200, got ${status}`);
  }

  fs.mkdirSync(OUT_DIR, { recursive: true });
  fs.writeFileSync(OUT_FILE, JSON.stringify({ status }, null, 2) + '\n');
  console.log(`Wrote status=${status} to ${OUT_FILE}`);
}

main().catch((err) => {
  console.error(err.message);
  process.exit(1);
});

